import os
import time


os.environ["TIME_STARTED"] = str(int(time.time()))  # setting the time the process started.
os.environ["REPOMAN_START_TIME"] = str(int(time.time()))  # setting the time the process started.

import sys
import io
import contextlib
import platform
import struct

import packmanapi
from repoman_bootstrapper import repoman_bootstrap

REPO_ROOT = os.path.join(os.path.dirname(os.path.realpath(__file__)), "../..")
REPO_DEPS_FILE = os.path.join(REPO_ROOT, "deps/repo-deps.packman.xml")
# Exclude repo_conan (tagged conan-only) when not using Conan, to save disk (e.g. CI arm devfull).
# Parse early so bootstrap can pull repo_conan when --use-conan is passed (before argparse runs).
_use_conan = (
    os.environ.get("OMNI_USE_CONAN", "").lower() in ("1", "true", "yes")
    or "--use-conan" in sys.argv
)
REPO_DEPS_EXCLUDE_TAGS = [] if _use_conan else ["conan-only"]

# No ARM binaries for WoA for many packages, but x86 fallback works fine, so WAR and use x86 binaries for WoA
def _patch_windows_arm64_x64_fallback():
    if os.name != "nt":
        return

    original_machine = platform.machine
    original_uname = platform.uname

    if original_machine() != "ARM64":
        return

    def _machine():
        machine = original_machine()
        return "AMD64" if machine == "ARM64" else machine

    def _uname():
        uname = original_uname()
        if uname.system == "Windows" and uname.machine == "ARM64":
            return uname._replace(machine="AMD64")
        return uname

    platform.machine = _machine
    platform.uname = _uname

def replace_python_process():
    """Replace python version with 3.12.

    We currently run with packman that is on 3.10, but we need 3.11. We can replace using "[repo.python_executable]" feature of repo_man,
    but it adds more overhead. It starts and configures the tool first and then runs again.
    """

    if sys.version_info.major == 3 and sys.version_info.minor == 12:
        return

    import platform

    operating_system = platform.system().lower()
    arch = platform.machine()
    if arch == "AMD64":
        arch = "x86_64"


    platform_host = f"{operating_system}-{arch}"
    is_windows = operating_system == "windows"
    python_path = packmanapi.install("python", f"3.12.10+nv1-{platform_host}")["python"]
    python_exec = python_path + "/" + ("python" if is_windows else "python")

    if is_windows:
        import subprocess
        try:
            r = subprocess.run([python_exec] + sys.argv)
            sys.exit(r.returncode)
        except Exception as e:
            print(e)
            sys.exit(1)
    else:
        os.execv(python_exec, [python_exec] + sys.argv)


def bootstrap():
    """
    Bootstrap all omni.repo modules.

    Pull with packman from repo.packman.xml and add them all to python sys.path to enable importing.
    """
    replace_python_process()
    with contextlib.redirect_stdout(io.StringIO()):
        deps = packmanapi.pull(REPO_DEPS_FILE, exclude_tags=REPO_DEPS_EXCLUDE_TAGS)
    for dep_path in deps.values():
        if dep_path not in sys.path:
            sys.path.append(dep_path)


if __name__ == "__main__":
    repoman_bootstrap()
    _patch_windows_arm64_x64_fallback()
    bootstrap()
    import omni.repo.man
    omni.repo.man.main(REPO_ROOT)
